INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('space-everyday-participation','problem_space','Participation in everyday life','Explore frictions between what people value doing and what their environments let them do. Scope includes home, neighbourhood and social participation, with overlaps into care work and provision. Excludes a general catalogue of diseases or communication products. Boundaries remain revisable.','interpretation','{"basis":"not_applicable","rationale":"Editorial boundary informed by WHO context; not a validated universal taxonomy."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('aspiration-valued-activities','aspiration','Continue activities that matter to me','Candidate aspiration to investigate in the person’s own terms: continue relationships and activities they value, with agency over help.','hypothesis','{"basis":"not_assessed","rationale":"Requires field research; not an observed or verified claim."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('problem-environmental-barriers','problem','Environments can obstruct valued activities','Physical and social environments can constrain what older people are able to do.','documented','{"basis":"single_source","rationale":"Supported at a broad global level by WHO; local mechanisms and distribution remain unresearched."}'::jsonb,'{"geography":"global","setting":"homes, neighbourhoods and communities","population":"older people; heterogeneous needs"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('cause-environment-capacity-fit','systemic_cause','Fit between environments and capacity','WHO describes environments as affecting health through barriers and incentives and enabling valued activity despite capacity loss. This is a broad mechanism, not a measured local causal effect.','documented','{"basis":"single_source","rationale":"Institutional synthesis; no local causal estimate."}'::jsonb,'{"geography":"global","setting":"physical and social environments","population":"older people"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('problem-digital-family-contact','problem','Difficulty initiating digital family contact','Candidate question: in which situations do digital interfaces obstruct family contact for an older person, and whose goal does contact serve?','candidate','{"basis":"not_assessed","rationale":"Requires field research; not an observed or verified claim."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('situation-family-call','daily_situation','Initiating a family call at home','Illustrative research scenario: a person wants to call family at a time they choose. No person, interview, quotation or frequency is asserted.','illustrative','{"basis":"not_applicable","rationale":"A prompt for fieldwork, not an observed day-in-the-life."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('workaround-family-assistance','lived_workaround','Ask a relative to operate the interface','Hypothesized workaround to investigate: relying on a relative to set up or initiate contact. Do not display as observed lived experience until field evidence exists.','hypothesis','{"basis":"not_assessed","rationale":"Requires field research; not an observed or verified claim."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('response-who-decade','institutional_response','UN Decade of Healthy Ageing','WHO describes a collaborative programme that includes supportive communities, integrated care and access to long-term care.','documented','{"basis":"single_source","rationale":"Documents an institutional response, not proof of its outcomes."}'::jsonb,'{"geography":"global","setting":"public-health systems","population":"older people, families and communities"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('solution-amara-home','solution','Amara Home','The provider describes a preconfigured voice-operated device and family app for calls, photos and messages. This documents the offering, not effectiveness against loneliness.','documented','{"basis":"single_source","rationale":"Provider claim inspected; no independent outcome evaluation."}'::jsonb,'{"geography":"not assessed","setting":"home","population":"older users and families"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,'company-amara');
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('question-lived-needs','open_question','Whose aspiration is being served?','What do older adults want from contact, and how does that differ from family expectations? Recruit varied circumstances; preserve attributed observations.','open_question','{"basis":"not_assessed","rationale":"Requires field research; not an observed or verified claim."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('question-care-work','open_question','How does participation relate to care work?','What effects do support arrangements have on professional caregivers, provider workload and sustainable service provision? No effect direction is assumed.','open_question','{"basis":"not_assessed","rationale":"Requires field research; not an observed or verified claim."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
INSERT INTO atlas.objects(id,kind,title,statement,epistemic_status,confidence,scope,provenance,entry_id) VALUES ('question-response-outcomes','open_question','What does the response change?','Does easier initiation change valued contact, autonomy or work for families? Seek independent outcomes, costs, non-use and alternatives.','open_question','{"basis":"not_assessed","rationale":"Requires field research; not an observed or verified claim."}'::jsonb,'{"geography":"not established","setting":"not established","population":"not established"}'::jsonb,'{"batch":"atlas-first-slice-20261008","authored_by":"Codex","method":"Scoped editorial curation, independently of company themes"}'::jsonb,NULL);
